-- hrm.tg_policy_versions_fixed: A policy version in force is never changed except its end date (set once) and its status (active to retired), and only a draft may be deleted (FR-XM-05); refused with constraint ck_policy_versions_fixed.
create or replace function hrm.tg_policy_versions_fixed() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'DELETE' then
        if old.status <> 'draft' then
            raise exception 'policy version % is % and cannot be deleted', old.id, old.status
                using errcode = '23514', constraint = 'ck_policy_versions_fixed';
        end if;
        return old;
    end if;
    if old.status <> 'draft' and (
            (new.policy_id, new.version, new.parameters, new.is_overridden, new.valid_from, new.created_at, new.created_by)
            is distinct from
            (old.policy_id, old.version, old.parameters, old.is_overridden, old.valid_from, old.created_at, old.created_by)
            or (old.valid_to is not null and new.valid_to is distinct from old.valid_to)
            or not (new.status = old.status or (old.status = 'active' and new.status = 'retired'))) then
        raise exception 'policy version % is % and cannot be changed', old.id, old.status
            using errcode = '23514', constraint = 'ck_policy_versions_fixed';
    end if;
    return new;
end
$fn$;
create or replace trigger tg_policy_versions_fixed before update or delete on hrm.policy_versions
    for each row execute function hrm.tg_policy_versions_fixed();

-- hrm.tg_policy_assignments_checks: No two assignments of one policy type in one company overlap with the same precedence (constraint ck_policy_assignments_precedence_unique); an assignment changes only by its end date, set once (constraint ck_policy_assignments_fixed).
create or replace function hrm.tg_policy_assignments_checks() returns trigger
language plpgsql as $fn$
declare
    kind text;
begin
    if tg_op = 'UPDATE' and (
            (new.company_id, new.policy_id, new.precedence, new.rule, new.valid_from, new.created_at, new.created_by)
            is distinct from
            (old.company_id, old.policy_id, old.precedence, old.rule, old.valid_from, old.created_at, old.created_by)
            or (old.valid_to is not null and new.valid_to is distinct from old.valid_to)) then
        raise exception 'policy assignment % cannot be changed except by ending it', old.id
            using errcode = '23514', constraint = 'ck_policy_assignments_fixed';
    end if;
    select p.policy_type into kind from hrm.policies p where p.id = new.policy_id;
    if exists (
        select 1 from hrm.policy_assignments a
          join hrm.policies p on p.id = a.policy_id
         where a.id <> new.id and a.company_id = new.company_id and a.precedence = new.precedence and p.policy_type = kind
           and daterange(a.valid_from, a.valid_to, '[)') && daterange(new.valid_from, new.valid_to, '[)')) then
        raise exception 'another % assignment of company % has precedence % on some of these dates', kind, new.company_id, new.precedence
            using errcode = '23514', constraint = 'ck_policy_assignments_precedence_unique';
    end if;
    return new;
end
$fn$;
create or replace trigger tg_policy_assignments_checks before insert or update on hrm.policy_assignments
    for each row execute function hrm.tg_policy_assignments_checks();
